// One CSV row (from the csv node) -> one DDATA for the "mqtt sparkplug device" node.
// Every column except the index and the timestamp becomes a metric named
// PREFIX + column, which is how the proposed south.sparkplug.metrics names
// them (APU/<signal>). All metrics are Doubles. The first row also carries
// the metric definitions, which makes the device node publish its DBIRTH.
const PREFIX = env.get("PDM_METRIC_PREFIX") || "APU/";
const SKIP = ["", "col1", "Unnamed: 0", "timestamp"];
const row = msg.payload;
const ts = Date.parse(String(row.timestamp).trim().replace(" ", "T") + "Z");   // the CSV is in UTC
if (Number.isNaN(ts)) {
    node.warn("row without a readable timestamp: " + JSON.stringify(row));
    return null;
}
const metrics = [];
const definition = {};
for (const [column, value] of Object.entries(row)) {
    if (SKIP.includes(column)) continue;
    const number = Number(value);
    if (!Number.isFinite(number)) {
        node.warn("column " + column + " is not a number: " + value);
        return null;
    }
    metrics.push({ name: PREFIX + column, value: number, timestamp: ts });
    definition[PREFIX + column] = { dataType: "Double" };
}
const out = { payload: { metrics: metrics } };
if (!context.get("defined")) {
    out.definition = definition;
    context.set("defined", true);
}
return out;

// Set one value by hand (build guide R2b.7: a value set in Node-RED reaches
// ingest). Put a CSV column and a value in the inject node, for example
// {"column": "<a CSV column>", "value": 9.5}. Run the replay first: it
// defines the metrics (DBIRTH). The adapter keeps every other signal's last
// value, so this one change becomes a whole telemetry record.
const PREFIX = env.get("PDM_METRIC_PREFIX") || "APU/";
const column = msg.payload && msg.payload.column;
const value = Number(msg.payload && msg.payload.value);
if (!column || !Number.isFinite(value)) {
    node.warn('set the payload to {"column": "<a CSV column>", "value": <number>}');
    return null;
}
return { payload: { metrics: [{ name: PREFIX + column, value: value, timestamp: Date.now() }] } };
